# Residual terminal-payout and conditional censored-resolution models.
.cr_lgd_stage<-function(stage){fixed<-list(payout_definition='RESIDUAL_TERMINAL_GROSS_RECOVERY_OR_CURE_VALUE',cashflow_pattern='SINGLE_TERMINAL_PAYOUT_AFTER_REFERENCE',timing_outcome_independence='CONDITIONAL_ON_REFERENCE_COVARIATES',positive_distribution='lognormal',cashflow_completeness='COMPLETE_THROUGH_OBSERVATION_END',payout_horizon='ULTIMATE');if(!.cr_object(stage)||any(vapply(names(fixed),function(k)!identical(stage[[k]],fixed[[k]]),logical(1)))||!is.character(stage$timing_distribution)||length(stage$timing_distribution)!=1L||!(stage$timing_distribution%in%c('weibull','lognormal','loglogistic'))) .cr_error('RECOVERY_STAGE','Explicit residual terminal-payout stage and conditional timing/outcome independence required');.cr_lgd_scalar(stage$cure_residual_value_ratio,'cure_residual_value_ratio',0);.cr_string(stage$landmark_definition,'landmark_definition','RECOVERY_STAGE');stage}
.cr_lgd_episodes<-function(episodes,x,cutoff,currency,training=FALSE){rows<-.cr_data_rows(episodes,'episodes');.cr_data_unique(rows,'episode_id','episodes');if(length(rows)!=nrow(x)) .cr_error('INCOMPATIBLE_SHAPE','One episode per covariate row required');parsed<-list()
 for(row in rows){.cr_data_required(row,c('default_date','default_known_at','reference_date','reference_known_at','features_observed_at','features_known_at','currency','ead_at_default','residual_exposure_at_reference'));if(!all(c('resolution_date','resolution_known_at')%in%names(row))) .cr_error('DATA_SCHEMA','Explicit nullable resolution dates required')
  default<-.cr_data_date(row$default_date,'default_date');dk<-.cr_data_date(row$default_known_at,'default_known_at');ref<-.cr_data_date(row$reference_date,'reference_date');rk<-.cr_data_date(row$reference_known_at,'reference_known_at');fo<-.cr_data_date(row$features_observed_at,'features_observed_at');fk<-.cr_data_date(row$features_known_at,'features_known_at');end<-if(training).cr_data_date(row$observation_end,'observation_end')else cutoff
  if(!(default<=dk&&dk<=ref&&ref<=end&&end<=cutoff&&rk==ref&&fo<=fk&&fk<=ref)) .cr_error('RECOVERY_DATE','Default, landmark features and observation dates are inconsistent or unavailable at landmark');if(!identical(row$currency,currency)) .cr_error('TARGET_MISMATCH','Episode reporting currency differs');ead<-.cr_lgd_scalar(row$ead_at_default,'ead_at_default',0);residual<-.cr_lgd_scalar(row$residual_exposure_at_reference,'residual_exposure_at_reference',0);if(training&&residual<=0) .cr_error('RECOVERY_STAGE','Positive residual exposure needed to fit payout ratios')
