  duration<-as.numeric(if(closed)rd-ref else end-ref);if(training&&duration<=0) .cr_error('RECOVERY_DATE','Positive observed/censored follow-up required');cured<-0;value<-0
  if(closed){.cr_data_required(row,c('cured','cure_value'));if(!is.numeric(row$cured)||length(row$cured)!=1||!(row$cured%in%c(0,1))) .cr_error('RECOVERY_STAGE','Observed cure outcome must be binary zero/one');cured<-row$cured;value<-.cr_lgd_scalar(row$cure_value,'cure_value',0);if(cured==0&&value!=0) .cr_error('RECOVERY_STAGE','Noncured resolutions cannot carry cure asset value')}
  parsed[[length(parsed)+1L]]<-list(row=row,reference=ref,end=end,closed=closed,duration=duration,cured=cured,cure_value=value,ead=ead,residual=residual,resolution=rd)
 };list(rows=rows,parsed=parsed)}
.cr_lgd_flows<-function(cashflows,episodes,cutoff,currency){flows<-.cr_data_rows(cashflows,'cashflows');.cr_data_unique(flows,'cashflow_id','cashflows');out<-setNames(lapply(episodes,function(r)list()),vapply(episodes,`[[`,character(1),'episode_id'))
