.cr_lgd_terminal_amount<-function(ep,flows,stage){terminal<-numeric();for(flow in flows){date<-.cr_data_date(flow$cashflow_date,'cashflow_date');if(date<.cr_data_date(ep$row$default_date,'default_date')) .cr_error('RECOVERY_DATE','Cashflow precedes default');if(ep$reference<date&&date<=ep$end&&flow$kind=='RECOVERY'&&flow$amount>0){if(!ep$closed||date!=ep$resolution) .cr_error('RECOVERY_STAGE','Intermediate post-landmark recoveries violate the single terminal-payout model');terminal<-c(terminal,flow$amount)}};amount<-.cr_loss_sum(terminal);if(ep$closed&&ep$cured==1){expected<-.cr_loss_multiply(ep$residual,stage$cure_residual_value_ratio);if(amount!=0||abs(ep$cure_value-expected)>1e-12*max(abs(ep$cure_value),abs(expected))) .cr_error('RECOVERY_STAGE','Cure value must equal declared residual ratio and cannot duplicate terminal cash recovery')};amount}
fit_recovery_hurdle<-function(episodes,cashflows,X_train,feature_order,stage_spec,target,training,model_id,model_version,currency,fit_intercept=TRUE,context=NULL){stage<-.cr_lgd_stage(stage_spec);ctx<-.cr_lgd_target_context(target,.cr_lgd_currency(currency,context),model_version);if(!identical(target$horizon_role,'TIMING_REPORTING_REFERENCE')||!identical(target$event,'residual_terminal_loss_fraction')||!identical(target$probability_measure,'PHYSICAL')||!identical(target$conditioning,'given_default')||!identical(target$time_unit,'days')||!identical(target$currency,currency)) .cr_error('TARGET_MISMATCH','Declare ultimate residual_terminal_loss_fraction with horizon_role=TIMING_REPORTING_REFERENCE, PHYSICAL, given_default, days and currency');if(!identical(training$workout_population,'open_and_closed_defaulted_landmarks')) .cr_error('LGD_POPULATION','Declare open_and_closed_defaulted_landmarks training population');cutoff<-.cr_data_date(training$known_at,'training.known_at');des<-.cr_glm_design(X_train,feature_order,fit_intercept);x<-des$x;d<-des$d;parsed<-.cr_lgd_episodes(episodes,x,cutoff,currency,TRUE);rows<-parsed$rows;eps<-parsed$parsed;fl<-.cr_lgd_flows(cashflows,rows,cutoff,currency);amounts<-vapply(eps,function(e).cr_lgd_terminal_amount(e,fl$byid[[e$row$episode_id]],stage),numeric(1));closed<-vapply(eps,`[[`,logical(1),'closed');cured<-vapply(eps,`[[`,numeric(1),'cured');noncure<-closed&cured==0;positive<-noncure&amounts>0
