 model<-.cr_model(list(schema_version='1.0',model_id=model_id,model_version=model_version,method_id='lgd.fit_recovery_hurdle',feature_order=as.list(feature_order),parameters=parameters,preprocessing=list(transformation='identity'),target=target,training=training,diagnostics=diagnostics,provenance=list(data_origin=if(is.null(training$data_origin))'USER_SUPPLIED'else training$data_origin,parameter_origin='ESTIMATED')));model$training_input_fingerprint<-.cr_hash(list(episodes=rows,cashflows=fl$flows,X=.cr_lgd_matrix_rows(x)));.cr_fit_result(model,'lgd.fit_recovery_hurdle',diagnostics,ctx)}
.cr_lgd_hurdle_prediction<-function(model,X,feature_order,expected_target,default_condition,levels,context){p<-model$parameters;stage<-.cr_lgd_stage(p$stage_spec);target<-model$target;if(!identical(target$horizon_role,'TIMING_REPORTING_REFERENCE')||!identical(target$event,'residual_terminal_loss_fraction')||!identical(target$probability_measure,'PHYSICAL')||!identical(target$conditioning,'given_default')||!identical(target$time_unit,'days')||!identical(target$currency,p$currency)) .cr_error('TARGET_MISMATCH','Frozen ultimate residual payout target or horizon role is malformed');des<-.cr_glm_design(X,feature_order,p$fit_intercept);x<-des$x;d<-des$d;if(!identical(as.list(feature_order),model$feature_order)||!identical(.cr_hash(expected_target),.cr_hash(model$target))||!identical(default_condition,'given_default')||!identical(p$default_condition,default_condition)) .cr_error('TARGET_MISMATCH','Frozen residual target, feature order and conditioning must match');q<-if(is.null(levels))NULL else .cr_numeric(levels,'quantile_levels',vector_only=TRUE);if(!is.null(q)&&(any(q<=0|q>=1)||any(diff(q)<=0))) .cr_error('INVALID_QUANTILE','Strictly increasing interior quantile levels required');gates<-list();outside<-rep(FALSE,nrow(x))
 for(key in c('cure_gate','positive_gate')){component<-.cr_model(p[[key]]);if(component$training$known_at>model$training$known_at) .cr_error('INVALID_MODEL','Component model was fitted after the composite model knowledge date');if(component$method_id!='lgd.fit_fractional_lgd') .cr_error('INVALID_MODEL','Recovery gate must be a frozen fractional-logit model');r<-predict_lgd(component,X,feature_order,expected_target,default_condition);gates[[key]]<-unlist(r$value$mean_lgd);outside<-outside|unlist(r$diagnostics$outside_marginal_training_range)}
