estimate_open_workout_lgd<-function(episodes,cashflows,fitted_recovery_model,X,valuation_contracts,future_cost_cashflows,feature_order,expected_target,stage_spec,as_of,currency,extrapolation,context=NULL){model<-.cr_model(fitted_recovery_model);p<-model$parameters;stage<-.cr_lgd_stage(stage_spec);cutoff<-.cr_data_date(as_of,'as_of');ctx<-.cr_lgd_target_context(model$target,.cr_lgd_currency(currency,context),model$model_version)
