  if(ep$closed){if(length(costby[[eid]])) .cr_error('RECOVERY_STAGE','Closed final workout cannot retain unpaid future costs');cure_realized<-if(ep$cured==1).cr_loss_multiply(ep$cure_value,factor(as.character(ep$resolution)))else 0;future_tail<-0;status<-'OBSERVED_CLOSED'
  }else{dates<-valuation$future_resolution_dates;if(is.character(dates))dates<-as.list(dates);if(!is.list(dates)||!length(dates)) .cr_error('RECOVERY_CONTRACT','Open workouts require a future resolution grid');parsed_dates<-vapply(dates,function(v)as.numeric(.cr_data_date(v,'future_resolution_dates')),numeric(1));if(parsed_dates[1]<=as.numeric(cutoff)||any(diff(parsed_dates)<=0)) .cr_error('RECOVERY_DATE','Resolution grid must increase strictly after evaluation cutoff');grid<-parsed_dates-as.numeric(cutoff);age<-as.numeric(cutoff-ep$reference);path<-list(list(path_id=eid,start=age,stop=age+tail(grid,1),covariates=as.list(x[index,]),stratum='all',covariate_time=0));curve<-predict_event_curves(timing,path,grid,feature_order,timing$target,start_time=age,extrapolation=extrapolation)$value$curves[[1]];resolution_prob<-curve$marginal_probabilities$workout_resolution;tail_mass<-as.numeric(tail(unlist(curve$survival),1));expected<-.cr_loss_multiply(ep$residual,predictions$value$expected_terminal_value_ratio[[index]]);future_grid<-.cr_loss_sum(vapply(seq_along(dates),function(i).cr_loss_multiply(expected,resolution_prob[[i]],factor(dates[[i]])),numeric(1)));undiscounted_tail<-.cr_loss_multiply(expected,tail_mass);tail_factor<-valuation$tail_discount_factor
