 }
 .cr_result(list(episodes=outputs,as_of=as_of,currency=currency,extrapolation=extrapolation),'lgd.estimate_open_workout_lgd','loss_fraction',ctx,provenance=model$provenance,diagnostics=list(model_fingerprint=.cr_hash(model),stage_fingerprint=.cr_hash(stage),outside_marginal_training_range=predictions$diagnostics$outside_marginal_training_range,input_fingerprint=.cr_hash(list(episodes=rows,cashflows=flows,valuation_contracts=valuations,future_cost_cashflows=costs,X=.cr_lgd_matrix_rows(x)))),limitations=list('Single residual terminal gross payout or cure asset value, conditional on the declared landmark. Payout outcome/amount and resolution timing are conditionally independent; censoring is independent given covariates. Resolution within each interval is valued at its right endpoint. Supplied future costs are unconditional dated amounts and no additional costs are inferred. Unknown tail discount value prevents a final LGD estimate; supplied tail factors are user assumptions. No automatic floors, regulatory calibration or payment-path model is implied.'))
}
